/**
 * Repository contracts for the domain layer.
 *
 * Pure TypeScript contracts: every method returns a `Promise`, no SQL, no storage types, no
 * transaction objects. The SQLite implementation (D2) and the in-memory fakes (`./fakes.ts`)
 * satisfy these interfaces, so the agent tools (A2), the verify pipeline (V2) and the
 * notification tasks (N1) can be written and tested against fakes only.
 *
 * Shared conventions:
 * - IDs are generated by the repository on create; callers never pass ids.
 * - Timestamps are set by the repository (`created_at`, `updated_at`) from its clock.
 * - Entities are returned as fresh objects: mutating a returned object must never change the
 *   stored state (the SQLite implementation deserializes, the fakes copy).
 * - `null` means «not found»; repositories do not throw for lookups. Mutating methods throw
 *   `NotFoundError` when the target does not exist and `InvalidTransitionError` when the
 *   status machine (see `./status.ts`) forbids the change.
 * - `overdue` is derived (`active && due_at < now`) and never stored — see {@link AssignmentFilter}.
 *
 * Assignment items are managed by {@link AssignmentsRepo} (an item only exists inside an
 * assignment, and every consumer needs both), so there is no separate `ItemsRepo`.
 */

import type {
  Assignment,
  AssignmentItem,
  AssignmentSource,
  AssignmentStatus,
  AssignmentWithItems,
  CheckIn,
  DateInput,
  FindingVerdict,
  Id,
  IsoDateTime,
  Photo,
  PhotoKind,
  Role,
  Settings,
  SettingKey,
  TgBinding,
  User,
  Verification,
  VerificationFinding,
  VerificationStatus,
  VerificationWithFindings,
} from "./types.js";

// ---------------------------------------------------------------------------
// Input shapes
// ---------------------------------------------------------------------------

/** One item to create inside an assignment. */
export interface NewAssignmentItemInput {
  /** Human label, e.g. «№ 12». */
  label: string;
  note?: string | null;
  /** Display order; omitted → appended after existing items. */
  position?: number;
}

/** Input of {@link AssignmentsRepo.create}. */
export interface NewAssignmentInput {
  subject: string;
  /** Concrete due instant (resolve `settings.default_due` before calling). */
  due_at: IsoDateTime;
  source: AssignmentSource;
  note?: string | null;
  /** Usually at least one item; the intake flows always produce labels. */
  items?: readonly NewAssignmentItemInput[];
}

/** Filter of {@link AssignmentsRepo.list}. All given conditions are ANDed. */
export interface AssignmentFilter {
  /** One stored status or a set of them. */
  status?: AssignmentStatus | readonly AssignmentStatus[];
  /** Case-insensitive exact subject match (trimmed). */
  subject?: string;
  /** `due_at < dueBefore`. */
  dueBefore?: IsoDateTime;
  /** `due_at >= dueAfter`. */
  dueAfter?: IsoDateTime;
  /**
   * `false` — only assignments without any check-in (the reminder list, SPEC §5.6);
   * `true` — only assignments with at least one check-in.
   */
  hasCheckIn?: boolean;
  limit?: number;
  /** Skip the first `offset` rows of the ordered result (ascending `due_at`). */
  offset?: number;
}

/** Input of {@link CheckInsRepo.create}. */
export interface NewCheckInInput {
  assignment_id: Id;
  /** `users.id` of the reporting child. */
  child_user_id: Id;
  comment?: string | null;
}

/** Filter of {@link CheckInsRepo.list}. All given conditions are ANDed. */
export interface CheckInFilter {
  childUserId?: Id;
  /** `created_at >= since`. */
  since?: IsoDateTime;
  /** `created_at < until`. */
  until?: IsoDateTime;
  limit?: number;
}

/** Input of {@link PhotosRepo.create} — the file itself is written by `src/media` (P1). */
export interface NewPhotoInput {
  kind: PhotoKind;
  /** Path relative to the photo root. */
  path: string;
  mime: string;
}

/** One finding produced by the verify pipeline. */
export interface NewVerificationFindingInput {
  item_id: Id;
  verdict: FindingVerdict;
  comment?: string | null;
}

/** Input of {@link VerificationsRepo.createDraft}. */
export interface NewVerificationInput {
  checkin_id: Id;
  summary: string;
  /** Model id that produced the draft (config slot `verify`). */
  model: string;
  findings: readonly NewVerificationFindingInput[];
}

/** Filter of {@link VerificationsRepo.listByAssignment}. */
export interface VerificationFilter {
  status?: VerificationStatus | readonly VerificationStatus[];
}

/** Filter of {@link VerificationsRepo.list}. */
export interface VerificationListFilter extends VerificationFilter {
  checkinId?: Id;
  limit?: number;
}

/** Input of {@link UsersRepo.create}. */
export interface NewUserInput {
  openwebui_user_id: string;
  role: Role;
  name: string;
}

/** Input of {@link TgBindingsRepo.upsert}. */
export interface TgBindingInput {
  user_id: Id;
  chat_id: string;
}

// ---------------------------------------------------------------------------
// Repositories
// ---------------------------------------------------------------------------

/** Assignments and their items (SPEC §5.2 `assignments`, `assignment_items`). */
export interface AssignmentsRepo {
  /** Create an assignment together with its items. Created assignments are `active` (no drafts). */
  create(input: NewAssignmentInput): Promise<AssignmentWithItems>;

  get(id: Id): Promise<Assignment | null>;

  getWithItems(id: Id): Promise<AssignmentWithItems | null>;

  /** Ordered by `due_at` ascending, then `created_at`. `overdue` must be filtered by the caller. */
  list(filter?: AssignmentFilter): Promise<Assignment[]>;

  /** Same as {@link list}, with items attached (prompt/summary rendering). */
  listWithItems(filter?: AssignmentFilter): Promise<AssignmentWithItems[]>;

  /** Convenience: `{ status: "active" }`, ordered by `due_at`. */
  listActive(): Promise<Assignment[]>;

  /** Derived overdue: `status === "active" && due_at < now`. */
  listOverdue(now: DateInput): Promise<Assignment[]>;

  /** Active assignments with `from <= due_at < to` (reminder horizon, SPEC §5.6). */
  listDueWithin(from: DateInput, to: DateInput): Promise<Assignment[]>;

  /** Items of one assignment ordered by `position`, then `created_at`. */
  listItems(assignmentId: Id): Promise<AssignmentItem[]>;

  getItem(id: Id): Promise<AssignmentItem | null>;

  /** Append items; positions continue after the current last item. Bumps `updated_at`. */
  addItems(assignmentId: Id, items: readonly NewAssignmentItemInput[]): Promise<AssignmentItem[]>;

  /**
   * Raw status write for the agent tools, which apply the status machine themselves
   * (`applyAssignmentAction`) and must persist the resulting status.
   */
  setStatus(id: Id, status: AssignmentStatus): Promise<Assignment>;
}

/** Check-ins (SPEC §5.2 `checkins`, §5.4). */
export interface CheckInsRepo {
  create(input: NewCheckInInput): Promise<CheckIn>;

  get(id: Id): Promise<CheckIn | null>;

  /** All check-ins of an assignment, ascending `created_at` (latest last). */
  listByAssignment(assignmentId: Id): Promise<CheckIn[]>;

  /** Latest check-in of an assignment (the one the current verdict is about). */
  latestForAssignment(assignmentId: Id): Promise<CheckIn | null>;

  /** Check-ins of one child, ascending `created_at`. */
  listForChild(childUserId: Id, filter?: Omit<CheckInFilter, "childUserId">): Promise<CheckIn[]>;

  /** All check-ins since an instant (digest «что сдано сегодня», SPEC §5.6). */
  listSince(since: DateInput): Promise<CheckIn[]>;

  /** Bump `updated_at` after photos were appended (verdict is recomputed). */
  touch(id: Id): Promise<CheckIn>;
}

/** Photos and the check-in ↔ photo links (SPEC §5.2 `photos`, `checkin_photos`). */
export interface PhotosRepo {
  create(input: NewPhotoInput): Promise<Photo>;

  get(id: Id): Promise<Photo | null>;

  /** Photos attached to a check-in, ascending `created_at`. */
  listByCheckIn(checkinId: Id): Promise<Photo[]>;

  /** Photos of one kind (e.g. intake screenshots not yet linked to a check-in). */
  listByKind(kind: PhotoKind): Promise<Photo[]>;

  /** Link an existing photo to a check-in. Re-linking is a no-op. */
  attachToCheckIn(checkinId: Id, photoId: Id): Promise<void>;

  /** Remove a link; the photo row itself is kept. No-op when the link is absent. */
  detachFromCheckIn(checkinId: Id, photoId: Id): Promise<void>;

  /** Check-ins a photo is attached to (a photo may be reused, normally zero or one). */
  listCheckInIds(photoId: Id): Promise<Id[]>;
}

/** Verifications and findings (SPEC §5.2 `verifications`, `verification_findings`). */
export interface VerificationsRepo {
  /** Store a new `draft` verification with its findings. */
  createDraft(input: NewVerificationInput): Promise<VerificationWithFindings>;

  get(id: Id): Promise<Verification | null>;

  getWithFindings(id: Id): Promise<VerificationWithFindings | null>;

  /** All verifications of a check-in, ascending `created_at` (recomputes append). */
  listByCheckIn(checkinId: Id): Promise<Verification[]>;

  /**
   * Verdicts across all assignments, ascending `created_at` (parent «что там по проверкам»
   * without a specific assignment). Use {@link listPending} for the approval queue.
   */
  list(filter?: VerificationListFilter): Promise<Verification[]>;

  /** Verdicts of an assignment (via its check-ins), ascending `created_at`. */
  listByAssignment(assignmentId: Id, filter?: VerificationFilter): Promise<Verification[]>;

  /** Latest verification of a check-in, regardless of status. */
  latestForCheckIn(checkinId: Id): Promise<VerificationWithFindings | null>;

  /**
   * The verdict the parent decides about: the newest verification of a check-in when it is
   * still a draft, otherwise `null` (already decided, nothing to approve).
   */
  latestDraftForCheckIn(checkinId: Id): Promise<VerificationWithFindings | null>;

  /** Every draft, ascending `created_at` (parent «все черновики»). */
  listDrafts(): Promise<Verification[]>;

  /**
   * Drafts awaiting a decision, **only the latest draft per check-in** (digest and
   * `get_verdicts` for the parent): an older draft superseded by a recompute is not pending.
   */
  listPending(): Promise<Verification[]>;

  findings(verificationId: Id): Promise<VerificationFinding[]>;

  /** Record the parent decision. Throws `InvalidTransitionError` unless the draft is undecided. */
  decide(
    id: Id,
    decision: "approved" | "dismissed",
    decidedByUserId: Id | null,
    decidedAt?: DateInput,
  ): Promise<Verification>;
}

/** Users and their roles (SPEC §4, ADR 0004 `users`). */
export interface UsersRepo {
  create(input: NewUserInput): Promise<User>;

  /** Create or update the mapping for `openwebui_user_id` (role/name sync at login). */
  upsert(input: NewUserInput): Promise<User>;

  get(id: Id): Promise<User | null>;

  /** Role resolution: OpenWebUI account id → user. */
  getByOpenWebUiId(openwebuiUserId: string): Promise<User | null>;

  list(): Promise<User[]>;

  listByRole(role: Role): Promise<User[]>;

  setRole(id: Id, role: Role): Promise<User>;
}

/** Telegram chat bindings (SPEC §5.6 `tg_bindings`). */
export interface TgBindingsRepo {
  /** Bind a chat to a user; a user has at most one chat in the MVP. */
  upsert(input: TgBindingInput): Promise<TgBinding>;

  getByUserId(userId: Id): Promise<TgBinding | null>;

  list(): Promise<TgBinding[]>;

  /** Returns whether a binding existed. */
  remove(userId: Id): Promise<boolean>;
}

/**
 * Settings (SPEC §5.2 `settings`, §5.7).
 *
 * Values are validated before they reach the repository (`parseSettingValue` from
 * `./schemas.ts`); repositories accept only the typed shapes below and return **effective**
 * settings, i.e. stored overrides merged with the defaults from `./settings.ts`.
 */
export interface SettingsRepo {
  /** Effective settings: every key always present. */
  getAll(): Promise<Settings>;

  /** Effective value of one key (default when never set). */
  get<K extends SettingKey>(key: K): Promise<Settings[K]>;

  /** Persist one validated value and return the new effective settings. */
  set<K extends SettingKey>(key: K, value: Settings[K]): Promise<Settings>;

  /** Persist several validated values at once (used on bootstrap). */
  update(patch: Partial<Settings>): Promise<Settings>;
}

/** All repositories the core hands to tools and durable tasks. */
export interface Repos {
  users: UsersRepo;
  assignments: AssignmentsRepo;
  checkIns: CheckInsRepo;
  photos: PhotosRepo;
  verifications: VerificationsRepo;
  tgBindings: TgBindingsRepo;
  settings: SettingsRepo;
}
